'use strict';
let combatView=null;
class CombatView{
 constructor(board){this.board=board;this.battle=null;this.nodes=new Map();this.animations=new Set();this.jobs=new Set();this.epoch=0;this.sequence=0;this.speed=1;this.paused=false;this.finishing=false;this.lastEvents=null;this.seenEvents=new Set();this.effectsEpoch=0;this.pixelVfx=null;this.lanes=new Map();this.motion=matchMedia('(prefers-reduced-motion: reduce)');this.observer=new ResizeObserver(()=>{if(this.battle){this.measure();this.positionAll(true);}});this.observer.observe(board);}
 begin(b){this.reset();this.battle=b;this.board.classList.add('combat-mode');this.board.innerHTML=Array.from({length:b.config.board.columns*b.config.board.rows},(_,p)=>`<div class="cell ${p>=b.config.board.playerFirstRow*b.config.board.columns?'player-zone':''} ${p>=(b.config.board.playerFirstRow-1)*b.config.board.columns&&p<b.config.board.playerFirstRow*b.config.board.columns?'frontier':''}" data-pos="${p}" aria-hidden="true"></div>`).join('');this.actors=document.createElement('div');this.actors.className='combat-actors';this.fx=document.createElement('div');this.fx.className='combat-effects';this.fx.setAttribute('aria-hidden','true');this.board.append(this.actors,this.fx);if(typeof AutoPixelVfx!=='undefined')this.pixelVfx=new AutoPixelVfx.PixelVfx(this.fx,{reduced:this.motion.matches});this.measure();}
 measure(){this.pixelVfx?.resize(this.board.clientWidth,this.board.clientHeight);const rect=this.board.getBoundingClientRect();if(!rect.width||!this.battle)return;this.points=[...this.board.querySelectorAll(':scope > .cell')].map(el=>{const r=el.getBoundingClientRect();return {x:r.left-rect.left-this.board.clientLeft+r.width/2,y:r.top-rect.top-this.board.clientTop+r.height/2,w:Math.max(20,r.width-4),h:Math.max(20,r.height-4)};});}
 setSpeed(value){if(this.pixelVfx&&this.pixelVfx.reduced!==this.motion.matches){this.clearTransient();this.pixelVfx.reduced=this.motion.matches;}this.speed=value;this.board.style.setProperty('--combat-move-ms',this.motion.matches?'0ms':Math.max(70,320/value)+'ms');}
 render(b){const fresh=this.battle!==b;if(fresh)this.begin(b);this.setSpeed(speed);if(!this.points?.length)this.measure();for(const u of b.units){let entry=this.nodes.get(u.uid);if(!entry&&!u.dead&&u.hp>0){const node=document.createElement('button');node.className='combat-unit '+(u.team==='enemy'?'combat-enemy':'combat-ally');node.dataset.combat=u.uid;node.dataset.visualInstance=++this.sequence;node.dataset.pos=u.pos;node.setAttribute('aria-label',(u.team==='ally'?'아군 ':'적 ')+u.name);node.innerHTML='<div class="combat-body"><div class="combat-sprite">'+pawn(u,true)+'</div></div>';this.actors.append(node);entry={node,body:node.querySelector('.combat-body'),sprite:node.querySelector('.combat-sprite'),pawn:node.querySelector('.pawn'),pos:u.pos,dead:false};this.nodes.set(u.uid,entry);this.position(entry,u,true);this.animate(entry.body,[{opacity:0,transform:'scale(.7)'},{opacity:1,transform:'scale(1)'}],{duration:this.motion.matches?1:220},false);}
 if(!entry)continue;const moved=entry.pos!==u.pos;this.position(entry,u,false);if(moved&&!u.dead&&!this.motion.matches)this.animate(entry.sprite,[{transform:'translateY(0) rotate(-2deg)'},{transform:'translateY(-3px) rotate(2deg)',offset:.5},{transform:'translateY(0) rotate(0)'}],{duration:Math.max(70,300/this.speed)},false);
 entry.pos=u.pos;entry.node.dataset.pos=u.pos;entry.node.disabled=u.dead||u.hp<=0;entry.pawn.classList.toggle('selected',selectedBattle===u.uid);entry.node.classList.toggle('is-defeated',u.dead||u.hp<=0);entry.pawn.querySelector('.hp i').style.width=Math.max(0,u.hp/u.stats.HP*100)+'%';entry.pawn.querySelector('.mp i').style.width=(u.stats.MP?Math.max(0,Math.min(100,u.mp/u.stats.MP*100)):0)+'%';this.badge(entry,'.status-mark',u.statuses.map(s=>s.label).join(' · '),'status-mark');const shield=u.shields.reduce((n,s)=>n+(s.expires>b.time?s.amount:0),0);this.badge(entry,'.shield-mark',shield>0?'◈'+num(shield):'','shield-mark');}
 if(fresh)this.consume(b,b.events);}
 badge(entry,selector,text,cls){let el=entry.pawn.querySelector(selector);if(!text){el?.remove();return;}if(!el){el=document.createElement('span');el.className=cls;entry.pawn.append(el);}el.textContent=text;el.title=text;}
 position(entry,u,snap){const p=this.points?.[u.pos];if(!p)return;entry.node.style.width=p.w+'px';entry.node.style.height=p.h+'px';if(snap){entry.node.style.transition='none';entry.node.style.transform=`translate3d(${p.x-p.w/2}px,${p.y-p.h/2}px,0)`;entry.node.getBoundingClientRect();entry.node.style.transition='';}else if(entry.pos!==u.pos)entry.node.style.transform=`translate3d(${p.x-p.w/2}px,${p.y-p.h/2}px,0)`;}
 positionAll(snap){if(!this.battle)return;for(const u of this.battle.units){const e=this.nodes.get(u.uid);if(e)this.position(e,u,snap);}}
 point(uid,fallback){const entry=this.nodes.get(uid);if(entry?.node.isConnected){const board=this.board.getBoundingClientRect(),r=entry.node.getBoundingClientRect();return {x:r.left-board.left-this.board.clientLeft+r.width/2,y:r.top-board.top-this.board.clientTop+r.height/2,w:r.width,h:r.height};}return this.points?.[fallback]||{x:this.board.clientWidth/2,y:this.board.clientHeight/2,w:40,h:40};}
 animate(el,frames,options,remove=false,done=null){const epoch=this.epoch,anim=el.animate(frames,{easing:'ease-out',...options});this.animations.add(anim);if(this.paused)anim.pause();anim.onfinish=()=>{this.animations.delete(anim);if(epoch!==this.epoch)return;if(remove)el.remove();done?.();};anim.oncancel=()=>{this.animations.delete(anim);if(remove)el.remove();};return anim;}
 schedule(ms,fn){const epoch=this.epoch,job={remaining:ms,due:0,id:null,fn:()=>{this.jobs.delete(job);if(epoch===this.epoch)fn();}};this.jobs.add(job);if(!this.paused)this.startJob(job);return job;}
 startJob(job){job.due=performance.now()+job.remaining;job.id=setTimeout(job.fn,job.remaining);}
 effect(cls,p){if(!this.fx)return null;while(this.fx.childElementCount>=150)(this.fx.firstElementChild===this.pixelVfx?.canvas?this.fx.children[1]:this.fx.firstElementChild).remove();const el=document.createElement('div');el.className=cls;el.style.left=p.x+'px';el.style.top=p.y+'px';this.fx.append(el);return el;}
 figure(command,p){const lane=(this.lanes.get(command.target)||0)%4;this.lanes.set(command.target,lane+1);const point={...p,x:Math.max(27,Math.min(this.board.clientWidth-27,p.x+[-9,10,-2,15][lane])),y:Math.max(18,p.y-p.h*.48-lane*11)},el=this.effect('combat-number number-'+command.tone,point);if(!el)return;if((command.critical&&command.amount>0)||command.kind==='shield'){const tag=document.createElement('small'),value=document.createElement('b');tag.textContent=command.kind==='shield'?'보호막':'치명타';value.textContent=(command.kind==='shield'?'+':'−')+AutoCombatVisuals.numberText(command.amount);el.append(tag,value);}else el.textContent=command.text;el.dataset.kind=command.kind;if(command.amount!==undefined)el.dataset.amount=command.amount;const duration=this.motion.matches?450:Math.max(500,900/Math.sqrt(this.speed));this.animate(el,this.motion.matches?[{opacity:1},{opacity:0}]:[{opacity:0,transform:'translate(-50%,0) scale(.7)',offset:0},{opacity:1,transform:'translate(-50%,-8px) scale(1.08)',offset:.15},{opacity:1,transform:`translate(calc(-50% + ${lane%2?8:-8}px),-27px) scale(1)`,offset:.68},{opacity:0,transform:`translate(calc(-50% + ${lane%2?13:-13}px),-47px) scale(.96)`,offset:1}],{duration},true);}
 element(command){const spec=command.sourceId?W.combatSpec(command.sourceId):null;return AutoCombatVisuals.effectStyle(command.sourceTrait||spec?.trait);}
 skillEffect(command){const style=this.element(command),p=this.point(command.source,command.sourcePos);this.pulse(command.source,command.sourcePos,'cast',style.color);const glow=this.effect('combat-skill-glow',p);if(glow){glow.style.width=p.w*1.7+'px';glow.style.height=p.h*1.7+'px';glow.style.setProperty('--effect-color',style.color);glow.dataset.trait=style.trait;this.animate(glow,this.motion.matches?[{opacity:.45},{opacity:0}]:[{opacity:0,transform:'translate(-50%,-50%) scale(.6)'},{opacity:.7,transform:'translate(-50%,-50%) scale(1)',offset:.3},{opacity:0,transform:'translate(-50%,-50%) scale(1.25)'}],{duration:Math.max(240,650/Math.sqrt(this.speed))},true);}if(this.motion.matches)return;for(let i=0;i<5;i++){const angle=Math.PI*2*i/5-Math.PI/2,el=this.effect('combat-skill-spark',p);if(!el)continue;el.style.setProperty('--effect-color',style.color);const radius=p.w*.8;this.animate(el,[{opacity:.9,transform:'translate(-50%,-50%) scale(.4)'},{opacity:0,transform:`translate(calc(-50% + ${Math.cos(angle)*radius}px),calc(-50% + ${Math.sin(angle)*radius}px)) scale(.8)`}],{duration:Math.max(200,520/Math.sqrt(this.speed))},true);}}
 pulse(uid,position,kind,color){const p=this.point(uid,position),el=this.effect('combat-ring ring-'+kind,p);if(!el)return;el.style.setProperty('--effect-color',color||'#b49bdc');const size=p.w*(kind==='cast'?1.4:1.1);el.style.width=size+'px';el.style.height=size+'px';this.animate(el,this.motion.matches?[{opacity:.65},{opacity:0}]:[{opacity:.9,transform:'translate(-50%,-50%) scale(.4)'},{opacity:0,transform:'translate(-50%,-50%) scale(1.4)'}],{duration:Math.max(140,430/Math.sqrt(this.speed))},true);}
 impact(command){const entry=this.nodes.get(command.target);if(entry&&!entry.dead&&!this.motion.matches)this.animate(entry.body,[{filter:'brightness(1.8)',transform:'translateX(-2px)'},{filter:'brightness(1.25)',transform:'translateX(2px)',offset:.4},{filter:'brightness(1)',transform:'translateX(0)'}],{duration:Math.max(90,180/this.speed)},false);this.figure(command,this.point(command.target,command.targetPos));if(command.critical&&!(this.pixelVfx?.context&&AutoPixelVfx.mapping(command)))this.pulse(command.target,command.targetPos,'critical','#f4ce71');}
 acceptEvent(command){
  if(command.eventId!==undefined){
   if(this.seenEvents.has(command.eventId))return false;
   this.seenEvents.add(command.eventId);
   if(this.seenEvents.size>2048)this.seenEvents.delete(this.seenEvents.values().next().value);
  }
  return command.eventAt===undefined||Date.now()-command.eventAt<=500;
 }
 consume(b,events){if(this.battle!==b||this.lastEvents===events)return;this.lastEvents=events;const commands=AutoCombatVisuals.plan(events,b.units),delays=new Map(),attacked=new Set();for(const c of commands){if(!this.acceptEvent(c))continue;if(c.kind==='chainLightning'){if(c.sourceId==='C07'&&!c.sourceSummon)this.pixelVfx?.playChain(c,this.points?.[c.sourcePos]||this.point(c.source,c.sourcePos),this.points?.[c.primary.pos]||this.point(c.primary.uid,c.primary.pos),c.chains.map(t=>this.points?.[t.pos]||this.point(t.uid,t.pos)),this.speed);continue;}if(c.kind==='damage'){if(c.sourceId==='C07'&&c.skillVisual){this.impact(c);continue;}
  const isAttack=c.attackKind!=='dot'&&c.source!==c.target,source=this.nodes.get(c.source);let targetPoint=this.point(c.target,c.targetPos),sourcePoint=this.point(c.source,c.sourcePos),delay=0;
  const custom=this.pixelVfx?.context&&AutoPixelVfx.mapping(c);if(custom&&c.eventAt!==undefined){sourcePoint=this.points?.[c.sourcePos]||sourcePoint;targetPoint=this.points?.[c.targetPos]||targetPoint;}if(isAttack&&c.ranged&&!this.motion.matches){delay=Math.max(65,Math.min(210,90+Math.hypot(targetPoint.x-sourcePoint.x,targetPoint.y-sourcePoint.y)*.35)/this.speed);if(!custom){const el=this.effect('combat-projectile '+(c.damageType==='magic'?'magic-bolt':'physical-bolt')+(c.itemProc?' item-bolt':''),sourcePoint),angle=Math.atan2(targetPoint.y-sourcePoint.y,targetPoint.x-sourcePoint.x)*180/Math.PI;if(el){const style=this.element(c);el.style.setProperty('--projectile-color',style.color);el.dataset.trait=style.trait;this.animate(el,[{transform:`translate(-50%,-50%) rotate(${angle}deg)`},{transform:`translate(calc(-50% + ${targetPoint.x-sourcePoint.x}px),calc(-50% + ${targetPoint.y-sourcePoint.y}px)) rotate(${angle}deg)`}],{duration:delay,easing:'linear'},true);}}}
  if(custom&&!custom.flight)delay=0;if(isAttack&&source&&!attacked.has(c.source)&&!this.motion.matches){attacked.add(c.source);const dx=targetPoint.x-sourcePoint.x,dy=targetPoint.y-sourcePoint.y,len=Math.max(1,Math.hypot(dx,dy)),step=c.ranged?4:Math.min(13,sourcePoint.w*.28);this.animate(source.sprite,[{transform:'translate(0,0)'},{transform:`translate(${dx/len*step}px,${dy/len*step}px) scale(1.06)`,offset:.35},{transform:'translate(0,0) scale(1)'}],{duration:Math.max(100,230/this.speed)},false);}
  if(!custom&&isAttack&&!c.ranged&&c.amount>0)this.pulse(c.target,c.targetPos,'slash',this.element(c).color);delays.set(c.target,Math.max(delays.get(c.target)||0,delay));if(custom)this.pixelVfx.play(c,sourcePoint,targetPoint,delay,this.speed,()=>this.impact(c));else if(delay){const epoch=this.effectsEpoch;this.schedule(delay,()=>{if(epoch===this.effectsEpoch)this.impact(c);});}else this.impact(c);
 }else if(c.kind==='heal'||c.kind==='shield'||c.kind==='evade'){if(c.kind==='evade'&&this.pixelVfx?.context&&AutoPixelVfx.mapping(c)){const source=this.points?.[c.sourcePos]||this.point(c.source,c.sourcePos),target=this.points?.[c.targetPos]||this.point(c.target,c.targetPos),duration=Math.max(65,Math.min(210,90+Math.hypot(target.x-source.x,target.y-source.y)*.35)/this.speed);this.pixelVfx.play(c,source,target,duration,this.speed);}this.figure(c,this.point(c.target,c.targetPos));if(c.kind!=='evade')this.pulse(c.target,c.targetPos,c.kind,c.kind==='heal'?'#8dd5ac':'#8ebbea');}
 else if(c.kind==='cast')this.skillEffect(c);
 else if(c.kind==='spawn')this.pulse(c.target,c.targetPos,'spawn','#d7c18d');
 else if(c.kind==='death')this.die(c.target,delays.get(c.target)||0);
 }
 for(const u of b.units)if(u.dead&&this.nodes.has(u.uid)&&!this.nodes.get(u.uid).dead)this.die(u.uid,delays.get(u.uid)||0);
 }
 die(uid,delay){const entry=this.nodes.get(uid);if(!entry||entry.dead)return;entry.dead=true;entry.node.disabled=true;this.schedule(delay,()=>{this.animate(entry.body,this.motion.matches?[{opacity:1},{opacity:0}]:[{opacity:1,transform:'scale(1) rotate(0)'},{opacity:0,transform:'translateY(9px) scale(.65) rotate(12deg)'}],{duration:this.motion.matches?100:Math.max(160,320/Math.sqrt(this.speed))},false,()=>{entry.node.remove();if(this.nodes.get(uid)===entry)this.nodes.delete(uid);});});}
 finish(b,callback){this.finishing=true;this.schedule(this.motion.matches?500:Math.max(700,1100/Math.sqrt(this.speed)),()=>{if(this.battle!==b)return;this.finishing=false;this.reset();callback();});}
 clearTransient(){this.effectsEpoch++;this.pixelVfx?.clear();if(this.fx)for(const element of [...this.fx.children])if(element!==this.pixelVfx?.canvas)element.remove();this.lastEvents=this.battle?.events;}
 pause(){this.clearTransient();if(this.paused)return;this.paused=true;this.board.classList.add('combat-paused');for(const anim of this.animations)anim.pause();for(const job of this.jobs){if(job.id!==null)clearTimeout(job.id);job.remaining=Math.max(0,job.due-performance.now());job.id=null;}}
 resume(){if(!this.paused)return;this.paused=false;this.board.classList.remove('combat-paused');for(const anim of this.animations)anim.play();for(const job of this.jobs)this.startJob(job);}
 reset(){this.pixelVfx?.destroy();this.pixelVfx=null;this.epoch++;for(const job of this.jobs)if(job.id!==null)clearTimeout(job.id);this.jobs.clear();for(const anim of [...this.animations])anim.cancel();this.animations.clear();this.nodes.clear();this.seenEvents.clear();this.lanes.clear();this.actors?.remove();this.fx?.remove();this.actors=null;this.fx=null;this.battle=null;this.finishing=false;this.paused=false;this.lastEvents=null;this.board.classList.remove('combat-mode','combat-paused');}
}
function getCombatView(){if(!combatView)combatView=new CombatView($('board'));return combatView;}
